function M(n,t){let r=Math.floor(Date.now()/1e3)-n;if(r<0)return t?t("common.time.justNow"):"just now";if(r<60)return(t?t("common.time.secondsAgo"):"{count}s ago").replace("{count}",String(r));if(r<3600){let e=Math.floor(r/60);return(t?t("common.time.minutesAgo"):"{count}m ago").replace("{count}",String(e))}if(r<86400){let e=Math.floor(r/3600);return(t?t("common.time.hoursAgo"):"{count}h ago").replace("{count}",String(e))}if(r<604800){let e=Math.floor(r/86400);return(t?t("common.time.daysAgo"):"{count}d ago").replace("{count}",String(e))}return new Date(n*1e3).toLocaleDateString()}function d(n){let t=new Date(n*1e3),o=String(t.getHours()).padStart(2,"0"),r=String(t.getMinutes()).padStart(2,"0"),i=String(t.getSeconds()).padStart(2,"0");return`${o}:${r}:${i}`}var s=Date.UTC(2e3,0,1)/1e3,a=Date.UTC(2100,0,1)/1e3,f=Date.UTC(2e3,0,1),m=Date.UTC(2100,0,1),u=50*365.25*24*3600*1e3;function g(n){if(n==null)return null;if(typeof n=="string"){let t=n.trim();return!/^\d+$/.test(t)||t.length>15?null:Number(t)}return typeof n=="bigint"?n>BigInt(Number.MAX_SAFE_INTEGER)||n<0n?null:Number(n):typeof n=="number"?!Number.isFinite(n)||n<0?null:Math.trunc(n):null}function l(n,t=Date.now()){let o=g(n);if(o===null)return null;let r=String(Math.trunc(Math.abs(o))).length,i=o>=s&&o<=a,e=o>=f&&o<=m;if(r===13&&e||e&&!i)return Math.abs(o-t)<=u?o:null;if((r===10||r===11)&&i||i&&!e){let c=o*1e3;return Math.abs(c-t)<=u?c:null}return null}function S(n,t=Date.now()){return l(n,t)!==null}function h(n,t){let o=Math.abs(n-t);return o<3600?`${Math.max(1,Math.round(o/60))} min`:o<48*3600?`${Math.round(o/3600)} h`:`${Math.round(o/86400)} d`}export{M as a,d as b,S as c,h as d};
